"""Generate spec/ATRAC3-tables.md from spec/reference/at3_tables.py and binary-derived constants."""
import os, sys, math
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'spec', 'reference'))
sys.path.insert(0, os.path.dirname(__file__))
import at3_tables as T
from peutil import f32s

L = []
w = L.append
w('# ATRAC3 specification: Appendix A, tables\n')
w('Generated by `tools/gen_spec_tables.py` from data extracted from `psp_at3tool.exe`. '
  'Do not edit by hand.\n')
w('## A.1 Subband (block floating unit) boundaries\n')
w('32 subbands over the 1024 spectral lines of a sound unit. Subband *i* covers lines '
  '`SUBBAND_START[i]` .. `SUBBAND_START[i+1]-1`.\n')
w('| i | start | width | i | start | width |\n|---|---|---|---|---|---|')
S = T.SUBBAND_START
for i in range(16):
    j = i + 16
    w('| %d | %d | %d | %d | %d | %d |' % (i, S[i], S[i+1]-S[i], j, S[j], S[j+1]-S[j]))
w('')
w('## A.2 Scale factors\n')
w('`SF[i] = 2^((i - 15) / 3)`, i = 0..63 (SF[0] = 1/32, SF[15] = 1, SF[63] = 65536). '
  'The binary stores these as IEEE single precision (table at 0x4BEBE8); values equal '
  'the formula rounded to float32.\n')
w('## A.3 Quantiser selectors\n')
w('| selector | levels | mantissa range | MAX_QUANT (divisor) | values per codeword |\n|---|---|---|---|---|')
rng = {1: '-1..1', 2: '-2..2', 3: '-3..3', 4: '-4..4', 5: '-7..7', 6: '-15..15', 7: '-31..31'}
for s in range(1, 8):
    w('| %d | %s | %s | %s | %d |' % (s, {1:3,2:5,3:7,4:9,5:15,6:31,7:63}[s], rng[s], T.MAX_QUANT[s], 2 if s == 1 else 1))
w('\nSelector 0 means "subband not coded" (all lines zero).\n')
w('## A.4 Mantissa code tables\n')
w('Codewords are written MSB first. For selector 1 each codeword carries a *pair* of mantissas '
  '(first, second). Coding mode 0 = variable length (Huffman), coding mode 1 = constant length (CLC).\n')
for mode in (0, 1):
    for sel in range(1, 8):
        tab = T.CODES[(mode, sel)]
        w('### %s, selector %d\n' % ('VLC (mode 0)' if mode == 0 else 'CLC (mode 1)', sel))
        items = sorted(tab.items(), key=lambda kv: (kv[1] if sel > 1 else kv[1][0] * 4 + kv[1][1]))
        if sel > 1:
            items = sorted(tab.items(), key=lambda kv: (abs(kv[1]), -kv[1]))
        w('| mantissa | code | mantissa | code | mantissa | code |\n|---|---|---|---|---|---|')
        cells = ['| %s | `%s` ' % (str(v).replace(' ', ''), c) for c, v in items]
        while len(cells) % 3: cells.append('| | ')
        for k in range(0, len(cells), 3):
            w(''.join(cells[k:k+3]) + '|')
        w('')
w('## A.5 IMDCT window\n')
w('For i = 0..255, with j = 255 - i:\n\n```\nwi = sin(((i + 0.5)/256 - 0.5)·π) + 1\nwj = sin(((j + 0.5)/256 - 0.5)·π) + 1\n'
  'w[i] = w[511 - i] = wi / (0.5·(wi² + wj²))\n```\n')
w('## A.6 QMF prototype filter\n')
w('48-tap symmetric prototype; `h[i] = h[47 - i] = HALF[i]` for i = 0..23. Synthesis uses `2·h`.\n')
half = [-0.00001461907, -0.00009205479, -0.000056157569, 0.00030117269, 0.0002422519,
        -0.00085293897, -0.0005205574, 0.0020340169, 0.00078333891, -0.0042153862,
        -0.00075614988, 0.0078402944, -0.000061169922, -0.01344162, 0.0024626821,
        0.021736089, -0.007801671, -0.034090221, 0.01880949, 0.054326009,
        -0.043596379, -0.099384367, 0.13207909, 0.46424159]
w('```')
for k in range(0, 24, 4):
    w('  ' + ', '.join('%.11g' % v for v in half[k:k+4]) + ',')
w('```\n')
w('## A.7 Gain control\n')
w('Level code L (4 bits) means gain `2^(4 - L)` (L = 4 is unity). Location code P (5 bits) means sample `8·P` '
  'within the 256-sample QMF-band block. Interpolation between levels uses the factor `2^(-1/8)` per step '
  '(table 0x48D770: `2^(-k/8)`, k = 0..7).\n')
w('## A.8 Joint-stereo weights\n')
w('Weight index W = (flag << 3) | level. `a = 2·level/7`, `b = 2·sqrt(2 - (level/7)²)`; '
  'flag 0 gives (w0, w1) = (a, b), flag 1 gives (b, a). Level 7 gives (2, 2) = no weighting.\n')
wt = f32s(0x48d6b0, 32)
w('| W | w0 | w1 | W | w0 | w1 |\n|---|---|---|---|---|---|')
for i in range(8):
    w('| %d | %.7g | %.7g | %d | %.7g | %.7g |' % (i, wt[2*i], wt[2*i+1], i+8, wt[2*i+16], wt[2*i+17]))
w('\nMatrix selector M (2 bits): M = 0 → (c0, c1) = (0, 1); M = 1 → (1, 1); M = 2 → invalid '
  '(Sony decoder rejects the frame); M = 3 → (0.5, 0.5).\n')
open(os.path.join(os.path.dirname(__file__), '..', 'spec', 'ATRAC3-tables.md'), 'w').write('\n'.join(L) + '\n')
print('written')
